class Group:
    def __init__(self, members: list[str]) -> None:
        if not members:
            raise ValueError("Group must have at least one member.")
        # Preserve member order, ensure uniqueness
        self.members = list(dict.fromkeys(members))
        # Keep net balances in cents (integer) to avoid floating-point issues
        self._balances_cents: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Amount must be strictly positive.")

        if payer not in self._balances_cents:
            raise ValueError(f"Payer '{payer}' is not a member of the group.")

        if participants is None:
            parts = list(self.members)
        else:
            if not participants:
                raise ValueError("Participants list cannot be empty.")
            parts = list(dict.fromkeys(participants))
            for p in parts:
                if p not in self._balances_cents:
                    raise ValueError(f"Participant '{p}' is not a member of the group.")

        total_cents = round(amount * 100)
        n = len(parts)

        # "When an amount cannot be split into equal cents, the leftover cents are
        # borne by the payer: every other participant owes exactly the amount
        # rounded down to the cent."
        base_cents = total_cents // n
        remainder = total_cents % n

        # Credit the payer the entire amount paid
        self._balances_cents[payer] += total_cents

        if payer in parts:
            # Other participants pay base_cents; payer pays base_cents + remainder
            for p in parts:
                if p == payer:
                    self._balances_cents[p] -= base_cents + remainder
                else:
                    self._balances_cents[p] -= base_cents
        else:
            # Payer is not in participants: every participant pays base_cents,
            # and payer absorbs the leftover remainder cents
            for p in parts:
                self._balances_cents[p] -= base_cents
            self._balances_cents[payer] -= remainder

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances_cents[m] / 100.0 for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Debtors have negative balance, creditors have positive balance
        debtors: list[list] = []
        creditors: list[list] = []

        for m in self.members:
            cents = self._balances_cents[m]
            if cents < 0:
                debtors.append([m, -cents])
            elif cents > 0:
                creditors.append([m, cents])

        transactions: list[tuple[str, str, float]] = []

        d_idx = 0
        c_idx = 0

        while d_idx < len(debtors) and c_idx < len(creditors):
            debtor_name, d_cents = debtors[d_idx]
            creditor_name, c_cents = creditors[c_idx]

            transfer_cents = min(d_cents, c_cents)
            if transfer_cents >= 100:  # At least 1.00
                transactions.append(
                    (debtor_name, creditor_name, transfer_cents / 100.0)
                )

            debtors[d_idx][1] -= transfer_cents
            creditors[c_idx][1] -= transfer_cents

            if debtors[d_idx][1] == 0:
                d_idx += 1
            if creditors[c_idx][1] == 0:
                c_idx += 1

        return transactions
